import express, { Request, Response } from "express";
import { CatalogueService } from "../application/CatalogueService";
import { CreateOrderInput, CreateProductInput } from "../application/OrderDtos";
import { OrderService } from "../application/OrderService";
import { DomainError } from "../domain/DomainError";
import { orderStatuses, OrderStatus } from "../domain/OrderStatus";
import { InMemoryOrderRepository } from "./InMemoryOrderRepository";
import { InMemoryProductRepository } from "./InMemoryProductRepository";

const isOrderStatus = (value: unknown): value is OrderStatus =>
  typeof value === "string" && (orderStatuses as readonly string[]).includes(value);

export const createApp = (): express.Express => {
  const products = new InMemoryProductRepository();
  const orders = new InMemoryOrderRepository();
  const catalogue = new CatalogueService(products);
  const orderService = new OrderService(orders, products);
  const app = express();
  app.use(express.json());

  app.post("/products", (request, response) => {
    try {
      response.status(201).json(catalogue.addProduct(request.body as CreateProductInput));
    } catch (error) { sendError(response, error); }
  });
  app.get("/products", (_request, response) => response.json(catalogue.listProducts()));
  app.post("/orders", (request, response) => {
    try {
      response.status(201).json(orderService.placeOrder(request.body as CreateOrderInput));
    } catch (error) { sendError(response, error); }
  });
  app.get("/orders", (request, response) => {
    const state = request.query.state;
    if (state !== undefined && !isOrderStatus(state)) {
      response.status(400).json({ error: "state must be a valid order status" });
      return;
    }
    response.json(orderService.listOrders(state));
  });
  app.post("/orders/:id/:action", (request, response) => {
    try {
      const action = request.params.action;
      if (action === "cancel") {
        response.json(orderService.cancelOrder(request.params.id));
        return;
      }
      if (!isOrderStatus(action) || action === "placed") {
        response.status(400).json({ error: "action must be paid, packed, shipped, delivered, or cancel" });
        return;
      }
      response.json(orderService.advanceOrder(request.params.id, action));
    } catch (error) { sendError(response, error); }
  });
  return app;
};

const sendError = (response: Response, error: unknown): void => {
  if (error instanceof DomainError) {
    response.status(400).json({ error: error.message });
    return;
  }
  response.status(500).json({ error: "Unexpected server error" });
};

export const startServer = (port = Number(process.env.PORT) || 3000): void => {
  createApp().listen(port, () => console.log(`Order fulfilment API listening on port ${port}`));
};

